#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    long long k;
    if (!(cin >> n >> m >> k)) return 0;
    vector<long long> a(n), b(m);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < m; i++) cin >> b[i];
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    int i = 0, j = 0, ans = 0;
    while (i < n && j < m) {
        if (b[j] < a[i] - k) {
            j++;
        } else if (b[j] > a[i] + k) {
            i++;
        } else {
            ans++;
            i++;
            j++;
        }
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, k;
    if (!(cin >> n >> k)) return 0;

    // Find minimal M such that M*(M-1)/2 >= k
    long long low_m = 0, high_m = n, M = n;
    while (low_m <= high_m) {
        long long mid = low_m + (high_m - low_m) / 2;
        if (mid * (mid - 1) / 2 >= k) {
            M = mid;
            high_m = mid - 1;
        } else {
            low_m = mid + 1;
        }
    }

    long long L = n - M;
    vector<int> ans;
    ans.reserve(n);
    for (int i = 1; i <= L; i++) {
        ans.push_back(i);
    }

    int low = L + 1, high = n;
    while (low <= high) {
        long long slots = high - low;
        if (k >= slots) {
            ans.push_back(high);
            k -= slots;
            high--;
        } else if (k > 0) {
            int pick = low + (int)k;
            ans.push_back(pick);
            for (int x = low; x < pick; x++) ans.push_back(x);
            for (int x = pick + 1; x <= high; x++) ans.push_back(x);
            k = 0;
            break;
        } else {
            ans.push_back(low);
            low++;
        }
    }

    for (int i = 0; i < n; i++) {
        cout << ans[i] << (i == n - 1 ? "" : " ");
    }
    cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, x;
    if (!(cin >> n >> x)) return 0;
    vector<int> h(n), s(n);
    for (int i = 0; i < n; i++) cin >> h[i];
    for (int i = 0; i < n; i++) cin >> s[i];

    vector<int> dp(x + 1, 0);
    for (int i = 0; i < n; i++) {
        int cost = h[i];
        int val = s[i];
        for (int w = x; w >= cost; w--) {
            dp[w] = max(dp[w], dp[w - cost] + val);
        }
    }
    cout << dp[x] << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>

using namespace std;

pair<int, int> bfs(int start, int n, const vector<vector<int>>& adj) {
    vector<int> dist(n + 1, -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    int far_node = start;
    int max_d = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (dist[u] > max_d) {
            max_d = dist[u];
            far_node = u;
        }
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return {far_node, max_d};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    auto [u, d1] = bfs(1, n, adj);
    auto [v, diameter] = bfs(u, n, adj);
    cout << diameter << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

void solve() {
    int n, k;
    if (!(cin >> n >> k)) return;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long min_diff = 3e18;
    long long best_x = a[0];
    for (int i = 0; i + k < n; i++) {
        long long diff = a[i + k] - a[i];
        if (diff < min_diff) {
            min_diff = diff;
            best_x = a[i] + diff / 2;
        }
    }
    cout << best_x << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    if (cin >> t) {
        while (t--) solve();
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <stack>
#include <algorithm>

using namespace std;

struct SegTree {
    int size;
    vector<int> tree;
    SegTree(int n) {
        size = 1;
        while (size <= n + 2) size <<= 1;
        tree.assign(2 * size, 0);
    }
    void update(int idx, int val) {
        int p = idx + size;
        tree[p] = max(tree[p], val);
        for (p >>= 1; p >= 1; p >>= 1) {
            tree[p] = max(tree[2 * p], tree[2 * p + 1]);
        }
    }
    int query(int l, int r) {
        if (l > r) return 0;
        int res = 0;
        for (l += size, r += size + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = max(res, tree[l++]);
            if (r & 1) res = max(res, tree[--r]);
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> h(n + 1);
    for (int i = 1; i <= n; i++) cin >> h[i];

    vector<int> L(n + 1), R(n + 1);
    stack<int> st;
    for (int i = 1; i <= n; i++) {
        while (!st.empty() && h[st.top()] < h[i]) st.pop();
        L[i] = st.empty() ? 0 : st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n; i >= 1; i--) {
        while (!st.empty() && h[st.top()] < h[i]) st.pop();
        R[i] = st.empty() ? n + 1 : st.top();
        st.push(i);
    }

    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i + 1;
    sort(order.begin(), order.end(), [&](int a, int b) {
        return h[a] < h[b];
    });

    SegTree seg(n);
    vector<int> dp(n + 1, 0);

    int ptr = 0;
    while (ptr < n) {
        int r = ptr;
        while (r < n && h[order[r]] == h[order[ptr]]) r++;
        // First compute DP for all in this group
        for (int i = ptr; i < r; i++) {
            int u = order[i];
            int ql = L[u] + 1;
            int qr = R[u] - 1;
            dp[u] = 1 + seg.query(ql, qr);
        }
        // Then insert into segment tree
        for (int i = ptr; i < r; i++) {
            int u = order[i];
            seg.update(u, dp[u]);
        }
        ptr = r;
    }

    int ans = 0;
    for (int i = 1; i <= n; i++) ans = max(ans, dp[i]);
    cout << ans << "\n";
    return 0;
}
